\u0031\u0042\u0057\u006f\u002a\u0064\u0043\u006a\u0076\u0056\u006e\u0060\u0062\u0027\u0065\u0049\u004a\u006a\u0064\u0034\u0054\u0073\u0076\u0042\u0050\u004a\u003a\u0020\u0057\u002c\u006f\u0034\u0035\u0053\u0070\u004c\u007c\u0052\u004b\u006e\u002d\u0077\u002d\u005c\u0048\u0047\u002c\u0035\u0040\u0033\u007b\u0058\u006f\u003c\u005b\u0069\u0057\u0072\u0079\u0075\u002b\u005a\u0073\u0079\u0058\u0071\u007d\u0072\u0043\u006e\u0058\u0078\u006e\u0061\u0056\u004b\u003f\u0040\u007e\u0031\u0032\u0079\u0041\u004e\u0037\u0057\u007e\u0061\u006f\u0039\u0055\u003b\u0050\u0039\u0031\u002c\u0044\u0041\u0045\u0041\u0054\u0057\u0024\u005f\u0070\u007d\u0032\u004f\u0032\u0074\u0077\u0026\u0028\u0025\u002b\u0021\u0020\u002a\u0045\u007e\u0028\u0054\u003e\u005f\u0054\u0053\u006e\u007d\u003e\u0021\u0058\u004e\u006a\u0057\u005f\u002b\u0063\u0031\u0073\u005c\u002f\u0027\u0024\u005b\u0075\u0042\u007c\u0063\u0028\u0056\u005b\u0045\u002a\u006e\u006c\u0072\u0024\u0076\u0050\u002e\u002f\u0038\u0029\u0043\u0054\u0025\u0050\u005f\u0066\u002b\u0068\u006a\u0053\u0040\u002a\u006b\u0033\u006b\u005d\u0041\u0075\u0035\u0047\u007b\u0079\u006b\u002f\u0079\u0030\u0078\u0062\u0021\u0053\u002e\u004e\u0041\u0023\u0037\u0058\u0074\u0045\u0065\u002d\u0032\u002b\u0063\u006a\u0027\u004f\u0037\u003d\u002e\u0033\u0038\u0023\u0049\u0049\u003a\u0067\u0033\u0040\u0075\u0027\u0022\u0046\u0070\u0057\u007e\u005e\u006d\u0043\u005f\u002f\u0038\u007a\u002a\u002e\u0069\u0068\u0041\u006b\u0059\u0035\u003d\u003a\u0052\u0036\u0070\u007b\u002f\u0036\u0052\u0072\u002d\u0067\u002a\u0069\u005d\u0048\u0065\u0039\u0056\u0076\u005a\u0078\u0030\u0035\u003f\u005e\u0067\u0077\u0046\u005f\u0039\u003e\u0051\u0055\u0065\u006b\u002b\u0024\u0022\u0073\u0046\u006d\u007e\u004f\u0069\u0045\u007c\u0036\u0044\u004c\u0037\u0041\u004c\u0042\u0065\u006e\u0034\u0035\u005e\u005a\u0049\u0050\u004e\u005c\u0061\u0039\u005a\u006e\u005f\u0035\u0035\u0055\u004a\u0042\u004b\u007c\u003d\u003a\u006e\u0028\u005c\u004b\u0033\u007d\u0029\u006d\u007b\u0050\u0042\u005f\u003c\u0031\u0073\u0041\u0040\u005b\u0039\u002a\u0058\u006b\u0059\u0045\u0024\u0067\u0031\u0071\u0076\u0021\u0060\u0036\u007e\u0026\u006a\u002a\u003c\u0064\u0046\u0049\u007e\u005b\u005c\u004b\u0070\u0041\u002e\u0049\u006e\u006b\u0071\u003b\u007d\u0053\u007c\u0028\u0074\u007e\u004d\u007a\u0043\u007a\u0027\u0020\u0029\u007d\u006e\u0037\u007c\u0077\u0042\u005e\u0041\u0032\u0059\u0044\u005c\u003c\u0052\u002c\u002b\u003e\u006d\u0054\u004a\u0028\u007e\u006d\u007e\u0039\u0041\u0062\u0037\u0074\u0060\u0049\u0033\u004e\u003f\u0073\u0073\u004e\u0072\u004a\u0054\u003b\u0070\u0029\u0024\u0061\u0053\u003f\u0055\u0050\u006a\u0020\u005a\u0069\u004f\u005c\u0033\u0074\u0023\u0046\u0034\u0069\u002f\u0023\u0049\u005e\u0027\u0058\u0073\u0020\u0025\u0035\u006f\u0066\u0023\u0052\u004d\u0055\u0079\u002c\u0071\u0032\u0021\u0068\u0053\u0060\u004d\u004e\u005b\u0045\u0035\u002f\u0065\u0062\u0020\u0061\u0058\u003c\u0052\u0070\u0055\u0036\u006a\u0057\u0026\u004c\u0038\u006e\u0060\u006a\u0024\u005e\u002c\u007e\u0024\u0049\u0029\u002c\u005d\u0024\u002a\u0061\u0047\u004b\u0028\u0043\u0030\u005c\u006f\u005f\u0074\u0075\u007a\u007a\u0027\u0034\u003d\u0049\u0055\u0061\u0058\u0068\u005b\u005e\u0037\u0020\u003c\u005a\u006c\u0042\u004a\u0065\u004b\u0079\u006e\u0068\u0060\u0055\u0071\u0025\u0073\u0074\u003c\u002e\u0041\u004b\u0069\u003a\u0065\u0029\u0067\u0073\u0037\u0065\u0073\u002c\u0026\u0028\u002e\u005f\u0044\u006b\u0029\u005e\u006a\u0056\u0022\u005c\u0049\u0075\u0059\u0064\u003e\u003e\u0075\u0034\u0076\u0024\u0078\u0056\u003a\u006e\u0035\u002a\u006b\u005b\u004c\u006e\u0047\u004b\u0054\u0041\u0059\u0031\u004a\u0078\u0077\u005b\u0027\u005d\u0035\u005f\u0043\u0061\u0020\u0026\u0050\u003c\u0052\u004c\u0074\u0021\u0071\u0035\u005d\u003d\u006a\u0073\u004d\u0045\u007b\u0020\u0056\u0041\u0025\u0045\u0068\u0062\u004e\u0046\u0078\u0071\u0070\u0052\u0023\u0039\u0061\u0078\u0069\u003e\u0071\u003b\u003a\u002d\u0034\u0041\u0066\u0056\u0074\u0028\u0077\u0027\u0024\u0063\u0050\u0078\u0032\u0020\u0070\u0045\u0047\u007b\u005c\u0074\u0059\u0033\u006e\u0023\u0041\u005d\u0041\u0023\u0038\u0074\u0026\u002e\u005f\u005e\u002d\u0057\u006c\u0063\u003f\u0025\u0065\u0039\u0053\u002c\u0046\u0073\u004b\u0023\u005c\u004c\u002f\u0066\u0041\u004f\u0079\u007e\u002c\u0053\u005b\u0067\u0040\u0025\u0024\u0020\u0024\u007d\u0059\u003f\u003c\u006e\u0032\u0073\u0034\u005d\u0057\u0068\u007d\u0063\u0057\u0066\u004a\u0078\u0053\u004f\u0035\u0072\u0077\u002a\u0048\u003a\u007b\u002d\u0056\u0051\u0053\u005f\u0072\u0048\u0076\u0062\u006f\u0023\u006a\u0051\u003a\u0032\u0045\u0048\u005c\u0071\u0024\u0023\u002a\u007d\u0059\u0051\u004f\u002c\u0040\u0050\u0021\u0057\u0066\u007c\u0060\u002f\u003e\u0070\u0049\u0038\u0068\u0071\u005e\u0040\u0048\u003a\u007b\u002b\u004d\u0045\u007c\u002e\u0023\u0057\u006b\u0043\u005a\u0054\u0073\u0043\u0076\u003e\u0056\u0050\u0055\u0037\u002d\u0036\u0073\u0061\u0040\u0032\u0057\u0044\u0049\u0078\u007d\u0038\u007e\u0031\u002a\u0024\u002b\u0045\u0060\u0049\u0070\u0023\u002a\u005f\u0044\u0069\u0058\u0076\u005f\u006d\u003c\u003b\u0040\u004b\u0067\u0051\u004c\u0045\u003d\u0064\u003f\u0041\u0027\u0055\u0035\u0032\u004c\u006e\u005e\u007a\u0029\u003c\u006d\u0035\u005b\u004f\u002b\u0077\u005b\u0058\u002e\u005e\u006a\u007e\u003b\u0077\u0034\u0072\u005b\u0022\u0029\u004d\u007d\u003d\u0072\u006e\u002b\u003f\u0036\u0061\u006f\u0066\u0075\u003d\u0023\u005a\u003c\u003d\u0032\u0077\u004b\u0056\u005a\u0020\u005b\u0049\u002f\u0023\u005c\u0051\u006c\u0062\u0069\u003f\u0055\u0048\u0034\u0020\u002c\u0031\u0029\u0056\u0069\u0041\u004f\u0071\u004a\u007b\u0022\u0051\u0043\u0034\u0041\u0020\u0071\u002a\u002a\u0030\u0022\u0060\u006a\u0054\u0036\u0076\u005e\u004d\u0028\u006b\u0047\u0021\u0068\u0028\u0037\u005c\u0049\u0079\u003c\u005c\u0020\u0064\u0029\u0060\u0049\u0037\u0054\u0022\u005c\u0039\u006f\u0023\u007e\u0038\u002e\u0048\u0041\u0030\u0067\u006f\u0071\u0058\u004d\u003d\u003b\u0072\u0079\u0042\u0026\u0046\u0066\u0062\u0058\u003b\u004e\u0078\u0079\u0076\u006a\u0048\u0039\u0072\u005a\u002f\u0046\u005b\u003c\u005f\u006d\u002d\u006b\u007a\u007c\u002c\u002b\u0061\u003c\u0074\u0046\u0044\u0057\u0039\u005c\u003a\u0045\u0035\u0041\u005e\u006a\u0062\u003b\u002b\u004f\u0076\u007d\u0059\u002a\u0077\u007b\u0065\u0075\u006f\u006e\u0079\u006e\u005b\u0047\u0043\u0060\u0061\u005b\u003d\u0042\u003a\u003c\u0030\u003e\u0029\u0065\u006c\u0062\u0053\u0028\u0041\u0079\u004a\u006a\u0031\u0044\u0061\u0036\u0050\u0077\u0052\u0069\u0055\u0058\u0042\u0055\u003d\u0042\u0031\u004e\u006f\u004d\u0079\u004a\u0041\u0070\u0027\u0077\u0043\u006d\u003f\u005d\u005b\u005b\u003e\u0053\u003a\u0028\u0060\u004d\u0029\u006c\u0051\u0062\u002a\u002d\u0048\u0043\u0052\u002f\u0031\u005b\u0050\u007b\u0072\u0061\u003a\u0024\u002b\u004e\u0072\u002e\u0022\u007d\u0056\u004f\u005d\u002d\u0049\u007c\u0076\u0070\u0063\u004b\u0078\u0071\u0049\u0059\u004b\u0063\u0077\u0050\u007c\u003f\u006a\u0024\u0028\u0030\u0061\u006f\u0032\u003e\u007d\u003b\u0060\u0077\u0032\u0042\u0027\u0073\u0073\u003d\u0043\u0042\u006e\u004a\u0028\u0028\u004d\u0064\u002e\u002f\u0059\u004a\u0045\u0073\u005a\u002b\u0074\u0063\u0023\u0034\u004d\u004e\u006f\u007a\u0047\u0040\u005d\u007e\u004f\u0068\u0055\u0056\u0041\u004a\u0037\u003a\u0063\u0057\u005d\u0072\u0075\u0078\u0034\u0070\u0064\u007c\u005e\u005a\u0074\u002f\u0031\u0040\u003d\u0045\u002b\u004b\u0058\u006a\u0035\u005c\u0042\u004c\u0025\u0040\u0073\u005c\u0054\u003d\u004f\u0023\u005e\u002c\u0049\u005f\u0054\u0071\u0054\u002b\u0072\u004b\u0055\u006a\u006d\u0060\u002c\u0040\u003a\u0058\u0044\u006a\u0027\u0053\u006c\u002e\u007b\u007e\u006e\u003b\u007d\u0045\u005c\u0043\u0068\u0070\u0074\u005b\u0072\u0020\u0042\u0041\u006d\u0039\u0078\u0052\u0055\u003e\u0042\u0020\u005a\u0044\u0024\u0072\u0044\u0042\u007c\u0076\u002d\u004a\u002f\u007a\u0074\u0079\u0045\u0026\u0063\u0050\u0029\u006b\u002d\u005f\u0025\u0067\u0024\u003f\u007e\u006e\u0032\u0044\u007b\u005a\u0025\u0059\u0020\u0066\u004a\u004d\u0061\u0040\u0065\u0028\u005f\u0035\u0073\u0077\u003e\u0078\u0071\u006d\u0046\u0078\u0031\u0041\u004f\u0071\u0074\u0051\u005a\u003e\u0038\u0030\u0042\u004c\u0066\u0072\u005b\u0030\u007b\u0042\u0071\u0073\u007d\u0033\u0046\u003b\u0049\u003a\u0063\u006c\u0049\u0068\u0072\u0065\u006f\u007c\u0063\u0025\u007d\u006e\u0029\u0039\u0050\u005c\u0067\u002a\u0055\u006b\u0022\u002e\u0049\u002e\u004a\u0078\u002c\u0041\u006d\u0050\u005e\u0054\u0023\u004f\u002e\u0068\u005f\u004e\u002a\u0059\u005e\u005e\u006f\u0054\u007e\u0062\u007b\u002d\u0077\u0040\u005b\u0074\u006a\u0038\u003a\u0075\u007d\u0054\u0025\u0035\u0024\u0029\u0067\u004d\u006f\u007d\u004c\u0071\u005f\u0027\u0070\u0033\u0051\u005b\u0041\u0065\u0067\u0042\u0070\u0022\u007e\u0073\u007a\u0040\u0029\u0034\u003e\u006b\u004c\u005f\u0045\u0072\u0046\u005c\u0045\u005f\u0055\u003c\u0038\u007b\u0059\u0040\u004e\u006f\u005e\u006b\u0027\u0035\u0059\u0067\u0063\u0043\u0069\u002a\u0041\u003b\u0075\u0043\u0064\u0070\u0063\u003d\u003e\u0075\u0069\u004a\u0052\u002c\u004c\u0054\u0038\u006c\u0077\u003b\u0021\u0030\u0038\u0077\u0036\u0027\u007a\u0054\u004d\u0064\u0034\u0074\u0068\u002e\u0037\u0072\u005d\u0054\u0037\u002a\u0026\u006c\u0039\u007c\u004e\u004c\u0020\u0047\u0066\u0033\u006d\u004f\u003d\u006e\u0074\u005a\u003e\u0037\u0054\u0059\u0077\u0041\u0049\u0020\u004f\u0045\u003c\u005b\u003a\u0021\u002b\u007b\u005e\u0049\u0027\u0068\u0054\u005a\u0024\u0050\u0050\u007d\u005f\u0073\u004b\u0039\u0069\u005f\u0059\u0066\u0060\u0061\u0050\u007c\u0041\u0064\u004f\u0023\u007d\u005f\u006d\u004a\u003a\u0032\u007b\u005e\u002c\u0020\u003a\u0039\u0021\u0044\u0055\u0050\u007b\u0039\u0043\u0034\u003e\u0038\u0043\u0034\u0068\u0052\u0079\u0076\u003f\u0062\u0041\u004e\u0023\u0039\u002d\u0063\u003a\u007d\u003b\u003b\u0025\u002f\u0069\u0074\u0045\u0077\u0020\u0064\u0021\u004d\u0024\u0026\u0044\u0032\u005e\u004d\u004e\u002e\u0020\u007b\u002f\u007b\u002e\u0054\u0060\u003e\u0041\u006d\u003a\u006d\u0044\u0066\u005d\u0039\u0050\u002c\u003a\u0029\u0051\u007d\u0057\u0033\u006b\u0024\u0021\u0031\u003e\u0048\u0059\u007a\u0060\u0041\u0066\u0079\u003a\u0067\u004d\u004e\u005c\u0070\u0032\u0078\u0065\u006f\u0053\u0056\u006d\u0057\u0041\u0045\u004a\u003f\u007c\u002b\u0043\u003b\u003b\u004d\u002e\u0068\u0064\u0063\u0071\u003d\u0046\u0072\u0066\u003a\u004a\u0062\u0065\u0044\u004b\u006d\u0033\u002d\u0051\u0066\u0077\u003c\u0056\u003a\u0067\u003c\u0033\u0041\u0066\u0076\u003b\u0061\u006b\u0076\u0065\u0052\u0023\u004c\u0062\u0034\u0049\u0028\u0029\u0026\u003e\u0071\u0064\u0058\u0071\u0050\u002f\u0054\u0027\u002a\u0059\u002f\u0052\u002c\u0073\u0056\u0026\u0079\u006c\u003c\u0071\u0038\u0051\u004b\u0047\u002e\u0030\u0060\u005c\u002b\u0064\u003f\u0035\u0056\u0073\u0074\u0047\u002e\u004d\u004f\u0037\u0040\u0023\u005e\u0074\u0045\u002c\u0044\u0061\u005f\u0055\u0051\u005d\u0026\u0021\u003f\u002c\u0025\u005e\u0054\u0076\u0033\u003b\u005d\u0047\u0034\u0023\u006c\u002a\u0024\u0053\u007e\u0020\u0058\u0042\u0038\u005f\u0045\u0062\u0064\u0022\u0039\u0068\u0057\u0067\u0071\u0069\u0026\u003a\u0044\u0073\u0042\u002c\u0059\u002b\u005f\u007e\u006d\u003f\u0028\u0050\u0047\u0030\u003e\u002a\u005e\u005e\u0073\u0020\u0054\u002d\u002b\u006b\u002a\u0059\u0076\u0069\u0061\u0057\u004f\u0053\u0023\u007c\u003d\u0074\u002b\u0021\u006c\u0072\u0033\u0067\u0026\u0047\u006a\u0046\u0024\u0075\u0053\u0030\u007b\u0057\u0048\u003b\u0061\u0032\u003f\u0022\u006a\u006c\u0039\u007e\u0036\u0026\u006f\u0033\u0054\u003f\u0031\u005a\u0077\u0054\u006c\u005b\u0034\u0075\u0071\u0050\u0026\u003f\u005e\u0064\u0055\u006b\u006e\u007a\u0040\u0073\u0043\u003e\u0041\u0032\u0021\u0065\u006c\u0042\u0033\u006f\u006b\u002a\u0030\u0061\u007a\u0055\u002e\u0056\u0063\u0052\u003e\u005e\u006c\u0059\u0055\u0072\u0052\u005b\u0058\u0056\u0068\u006c\u0053\u0065\u006b\u0027\u002a\u0045\u003e\u0075\u007b\u0034\u0029\u0068\u0077\u0040\u0076\u002a\u0038\u007a\u0059\u0024\u007b\u004c\u0028\u002f\u0037\u0035\u006e\u002f\u0059\u005f\u0035\u0056\u0067\u004d\u0063\u005d\u0035\u0067\u003b\u004c\u0038\u006e\u005d\u0069\u0023\u0027\u006a\u006f\u002f\u0057\u005f\u003d\u0039\u0036\u0052\u0053\u0048\u0079\u007b\u0069\u004a\u0059\u0033